'use strict';
const books=window.BOOKS;
const categories={'Computer Science':'Информатика','Design':'Дизайн','Engineering':'Инженерия','Mathematics':'Математика','Natural Sciences':'Естественные науки','Research & Writing':'Исследования'};
const colors=['#315044','#bc9c68','#334e61','#8b564b','#727d57','#70627c'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='kitaphana-demo-v1';
const languages={English:'Английский',Russian:'Русский',Kazakh:'Казахский',Turkmen:'Туркменский'};
function plural(n,[one,few,many]){const m10=n%10,m100=n%100;return m10===1&&m100!==11?one:m10>=2&&m10<=4&&(m100<12||m100>14)?few:many}
function fresh(){return {favorites:[],reservations:[],loans:[],history:[],stock:{},theme:window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light'}}
let state=fresh();try{const s=JSON.parse(localStorage.getItem(key));if(s&&['favorites','reservations','loans','history'].every(k=>Array.isArray(s[k])))state={...state,...s,stock:{...s.stock}}}catch{}
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('Хранилище недоступно. Изменения сохранятся только до закрытия страницы.')}}
const $=s=>document.querySelector(s);let tab='loans',timer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function color(b){return colors[Number(b.id.replace('b',''))%colors.length]}
function available(b){return Math.max(0,b.available+(state.stock[b.id]||0)-state.loans.filter(l=>l.id===b.id).length-state.reservations.filter(r=>r.id===b.id&&r.ready).length)}
function promote(){for(const r of state.reservations)if(!r.ready){const b=books.find(b=>b.id===r.id);if(b&&available(b)>0){r.ready=true;return r}}}
function badge(b){return b.type==='Electronic'?'<span class="badge digital">↗ Электронная книга</span>':available(b)>0?'<span class="badge">● В наличии · '+available(b)+'</span>':'<span class="badge waiting">◷ Лист ожидания</span>'}
function cover(b){return `<div class="cover" style="--cover:${color(b)}"><small>${esc(categories[b.category_name]||b.category_name)}</small><strong>${esc(b.title)}</strong><span>${esc(b.author)}</span></div>`}
function card(b){return `<article class="book-card"><button class="book-open" data-book="${b.id}" aria-label="Открыть ${esc(b.title)}"><div class="cover-stage">${cover(b)}</div><h3>${esc(b.title)}</h3><div class="author">${esc(b.author)}</div>${badge(b)}</button><button class="favorite" data-favorite="${b.id}" aria-label="${state.favorites.includes(b.id)?'Удалить из избранного':'Добавить в избранное'}" aria-pressed="${state.favorites.includes(b.id)}">${state.favorites.includes(b.id)?'♥':'♡'}</button></article>`}
function searchForm(value=''){return `<form class="search" id="search-form" role="search"><span aria-hidden="true">⌕</span><input name="q" aria-label="Название, автор или ISBN" placeholder="Название книги, автор или ISBN" value="${esc(value)}"><button class="button" type="submit">Найти ↗</button></form>`}
function stats(){return `<div class="stats"><div><strong>${books.length}</strong><span>${plural(books.length,['книга','книги','книг'])} в демокаталоге</span></div><div><strong>${Object.keys(categories).length}</strong><span>направлений знаний</span></div><div><strong>${books.filter(b=>b.type==='Electronic').length}</strong><span>${plural(books.filter(b=>b.type==='Electronic').length,['электронное издание','электронных издания','электронных изданий'])}</span></div></div>`}
function home(){return `<div class="wrap"><section class="hero"><div><div class="eyebrow">Ваш следующий шаг начинается с книги</div><h1>Открывайте книги.<br>Находите <em>свои идеи.</em></h1><p class="hero-description">Знания для учёбы, исследований и новых открытий. Вся университетская библиотека — в одном пространстве.</p>${searchForm()}<p class="hint">С чего начать?<a href="#catalog?q=design">Дизайн</a><a href="#catalog?q=algorithms">Алгоритмы</a><a href="#digital">Читать онлайн</a></p></div><div class="hero-art" role="img" aria-label="Две стилизованные книжные обложки"><div class="art-book one"><small>THE READING ROOM</small><strong>Мир<br>новых<br>открытий.</strong></div><div class="art-book two"><small>KITAPHANA / 2026</small><strong>Знания<br>без границ</strong><div class="orbit"></div></div><div class="art-label">ДЛЯ ЛЮБОПЫТНЫХ. ДЛЯ ВДОХНОВЛЁННЫХ. ДЛЯ ВАС.</div></div></section>${stats()}<section><div class="section-head"><div><div class="eyebrow">Ваша книжная полка начинается здесь</div><h2>Находки для нового семестра</h2></div><a href="#catalog">Весь каталог ↗</a></div><div class="chips">${['Все направления',...Object.values(categories)].map((c,i)=>`<a class="chip ${!i?'active':''}" href="#catalog${i?'?category='+encodeURIComponent(c):''}">${c}</a>`).join('')}</div><div class="book-grid">${[books[0],books[3],books[2],books[1]].map(card).join('')}</div></section><section class="digital-banner"><div><div class="eyebrow" style="color:inherit">Библиотека всегда рядом</div><h2>Хорошая идея не ждёт открытия библиотеки.</h2><p>Откройте электронные материалы прямо в браузере.</p></div><a class="button" href="#digital">Читать онлайн ↗</a></section></div>`}
function route(){const [page,query]=(location.hash.slice(1)||'home').split('?');return {page,params:new URLSearchParams(query||'')}}
function catalog(digital){const {params}=route(),q=params.get('q')||'',category=params.get('category')||'',sort=params.get('sort')||'title',only=params.get('available')==='1';let found=books.filter(b=>(!digital||b.type==='Electronic')&&(!category||categories[b.category_name]===category)&&(!only||b.type==='Electronic'||available(b)>0)&&`${b.title} ${b.author} ${b.isbn} ${categories[b.category_name]}`.toLocaleLowerCase().includes(q.toLocaleLowerCase()));found.sort((a,b)=>sort==='year'?b.year-a.year:sort==='popular'?b.borrow_count-a.borrow_count:a.title.localeCompare(b.title));return `<div class="wrap bottom-space"><div class="page-title"><div class="eyebrow">${digital?'Знания в цифровом формате':'Откройте свою следующую книгу'}</div><h1>${digital?'Электронная библиотека':'Каталог книг'}</h1><p class="muted">${digital?'Учебные материалы, которые всегда под рукой.':'От фундаментальных исследований до свежих идей — найдите своё.'}</p></div><div class="catalog-tools">${searchForm(q)}<select id="sort" aria-label="Сортировка"><option value="title" ${sort==='title'?'selected':''}>По названию: А–Я</option><option value="year" ${sort==='year'?'selected':''}>Сначала новые</option><option value="popular" ${sort==='popular'?'selected':''}>Чаще берут</option></select></div><div class="chips"><button class="chip ${!category?'active':''}" data-category="">Все направления</button>${Object.values(categories).map(c=>`<button class="chip ${category===c?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div class="filters"><label><input id="available" type="checkbox" ${only?'checked':''}> Только доступные сейчас</label><button class="button small outline" id="reset-filters">Сбросить фильтры</button><span class="count">Найдено: ${found.length} из ${digital?books.filter(b=>b.type==='Electronic').length:books.length}</span></div><div class="book-grid">${found.length?found.map(card).join(''):'<div class="empty"><h2>Книги не найдены</h2><p>Попробуйте другое название или сбросьте фильтры.</p></div>'}</div></div>`}
function date(s){return new Date(s).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}
function row(item,kind,staff=false){const b=books.find(b=>b.id===item.id);if(!b)return '';const subtitle=kind==='loans'?`Вернуть до ${date(item.due)}${new Date(item.due)<new Date()?' · Срок истёк':''}`:kind==='reservations'?(item.ready?'Экземпляр отложен. Можно получить в библиотеке.':'Ожидание свободного экземпляра'): `Возвращена ${date(item.returned)}`;return `<div class="loan-row"><div class="mini-cover" style="--cover:${color(b)}"></div><div class="row-info"><h3><button class="link" data-book="${b.id}">${esc(b.title)}</button></h3><p>${esc(b.author)}</p><p>${subtitle}</p></div><div class="actions">${kind==='reservations'?`${staff&&item.ready?`<button class="button small" data-action="issue" data-id="${b.id}">Выдать книгу</button>`:''}${staff&&!item.ready?`<button class="button small" data-action="arrive" data-id="${b.id}">Экземпляр вернулся</button>`:''}<button class="button small outline" data-action="cancel" data-id="${b.id}">Отменить бронь</button>`:kind==='loans'?staff?`<button class="button small" data-action="return" data-id="${b.id}">Принять возврат</button>`:`<button class="button small outline" data-action="renew" data-id="${b.id}" ${item.renewed?'disabled':''}>${item.renewed?'Уже продлена':'Продлить на 7 дней'}</button>`:''}</div></div>`}
function account(){const names={loans:'Мои книги',reservations:'Бронирования',favorites:'Избранное',history:'История'};return `<div class="wrap account-layout"><aside class="profile"><div class="avatar">А</div><h3>Александр · Демо</h3><small>Читательский билет № 2026-001</small><a href="#catalog">⌕ Найти новую книгу</a><a href="#staff">↗ Режим библиотекаря</a></aside><section><div class="page-title" style="padding-top:0"><div class="eyebrow">Ваше пространство для чтения</div><h1>Моя библиотека</h1><p class="muted">Книги, к которым хочется возвращаться.</p></div><div class="stats"><div><strong>${state.loans.length}</strong><span>${plural(state.loans.length,['книга','книги','книг'])} на руках</span></div><div><strong>${state.reservations.length}</strong><span>${plural(state.reservations.length,['бронирование','бронирования','бронирований'])}</span></div><div><strong>${state.favorites.length}</strong><span>в избранном</span></div></div><div class="account-tabs">${Object.entries(names).map(([k,v])=>`<button class="chip ${tab===k?'active':''}" data-tab="${k}">${v} · ${state[k].length}</button>`).join('')}</div>${state[tab].length?tab==='favorites'?`<div class="book-grid">${books.filter(b=>state.favorites.includes(b.id)).map(card).join('')}</div>`:state[tab].map(i=>row(i,tab)).join(''):`<div class="empty"><h2>${tab==='loans'?'Ваша следующая история впереди':tab==='reservations'?'Здесь появятся бронирования':tab==='favorites'?'Соберите свою книжную полку':'История пока пуста'}</h2><p class="muted">${tab==='loans'?'Найдите книгу, забронируйте её и оформите выдачу в режиме библиотекаря.':'Начните с каталога — там много интересного.'}</p><a class="button" href="#catalog" style="margin-top:18px">Перейти в каталог ↗</a></div>`}<p class="note" style="margin-top:24px">Это демонстрационный кабинет. Реальная регистрация не требуется; бронирования и избранное хранятся только в этом браузере.</p></section></div>`}
function staff(){return `<div class="wrap bottom-space"><div class="page-title"><div class="eyebrow">Демонстрация библиотечного процесса</div><h1>Рабочее место библиотекаря</h1><p class="muted">Выдача и возврат книг для демонстрационного читателя Александра.</p></div><p class="note">Переключение роли доступно для демонстрации. Это не система авторизации и не общая база библиотеки.</p><div class="panel"><h2>Бронирования · ${state.reservations.length}</h2>${state.reservations.length?state.reservations.map(i=>row(i,'reservations',true)).join(''):'<p class="muted">Новых заявок нет. Забронируйте книгу в каталоге.</p>'}</div><div class="panel"><h2>Выданные книги · ${state.loans.length}</h2>${state.loans.length?state.loans.map(i=>row(i,'loans',true)).join(''):'<p class="muted">Пока ни одна книга не выдана.</p>'}</div><div class="panel"><h2>Как показать работу системы</h2><p>1. Найдите доступную книгу в каталоге и забронируйте её.</p><p>2. Вернитесь сюда и нажмите «Выдать книгу».</p><p>3. Откройте кабинет читателя — книга появится в разделе «Мои книги».</p><p>4. Примите возврат здесь — запись переместится в историю.</p></div><button class="button outline" id="reset-demo">Сбросить мои демонстрационные данные</button></div>`}
function focusKey(el){if(!el||!$('#main').contains(el))return null;if(el.id)return '#'+el.id;for(const a of ['favorite','tab','category','book'])if(el.dataset[a]!==undefined)return `[data-${a}="${CSS.escape(el.dataset[a])}"]`;return null}
function render(){const {page}=route(),focused=focusKey(document.activeElement);$('#main').innerHTML=page==='catalog'?catalog(false):page==='digital'?catalog(true):page==='account'?account():page==='staff'?staff():page.startsWith('book/')?catalog(false):home();$('#nav-count').textContent=state.loans.length+state.reservations.length||'';document.body.classList.toggle('dark',state.theme==='dark');document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));if(focused)$(focused)?.focus();if(page.startsWith('book/'))openBook(page.slice(5))}
function openBook(id){const b=books.find(b=>b.id===id);if(!b){toast('Книга не найдена');return}const has=state.reservations.some(r=>r.id===id)||state.loans.some(r=>r.id===id);$('#book-content').innerHTML=`<div class="book-detail"><div class="cover-stage">${cover(b)}</div><div><div class="eyebrow">${esc(categories[b.category_name])}</div><h2>${esc(b.title)}</h2><p class="muted">${esc(b.author)}</p>${badge(b)}<p style="margin-top:16px">${b.type==='Electronic'?'Электронный учебный материал. В этой демоверсии доступна краткая авторская памятка по теме, а не полный текст издания.':'Издание для самостоятельного изучения, учебных занятий и исследовательской работы. Забронируйте экземпляр и получите его в библиотеке.'}</p><dl><dt>Издательство</dt><dd>${esc(b.publisher)}</dd><dt>Год</dt><dd>${b.year}</dd><dt>Язык издания</dt><dd>${esc(languages[b.language]||b.language)}</dd><dt>ISBN / ID</dt><dd>${esc(b.isbn)}</dd><dt>Срок выдачи</dt><dd>14 дней</dd></dl>${b.type==='Electronic'?`<button class="button" data-read="${id}">Открыть учебную памятку ↗</button>`:`<button class="button" data-action="reserve" data-id="${id}" ${has?'disabled':''}>${has?'Уже в вашей библиотеке':available(b)>0?'Забронировать книгу':'Встать в лист ожидания'}</button>`}<p class="muted" style="font-size:11px;margin-top:12px">Учебная демонстрация · без реального оформления выдачи</p></div></div>`;if(!$('#book-dialog').open)$('#book-dialog').showModal()}
const lessons={b29:['Реляционные базы данных','Таблица хранит записи одинаковой структуры. Первичный ключ отличает одну запись от другой, а внешний ключ связывает записи разных таблиц.','В библиотеке удобно разделить книги, читателей и выдачи. Одна книга может иметь несколько экземпляров; каждая выдача связывает конкретный экземпляр с читателем.','Практика: нарисуйте таблицы Book, Copy, Reader и Loan. Определите ключи и объясните, как запретить две активные выдачи одного экземпляра.'],b30:['Основы алгоритмов','Алгоритм — конечная последовательность шагов для решения задачи. Корректность означает, что для допустимого входа он даёт требуемый результат.','Линейный поиск просматривает элементы по очереди. Бинарный поиск использует отсортированный набор и на каждом шаге уменьшает область поиска вдвое.','Практика: сравните поиск названия в списке из 32 книг линейным и бинарным методом. Учтите необходимость сортировки.'],b31:['Как организовать исследование','Начните с вопроса, на который можно ответить с помощью доступных данных. Отделяйте наблюдения от предположений.','Записывайте источники, критерии отбора материалов и ограничения метода. Результат должен быть проверяемым другим исследователем.','Практика: сформулируйте вопрос об удобстве библиотечного каталога, выберите три задания для пользователей и определите показатели успешности.'],b32:['Доступный интерфейс','Интерфейс должен оставаться понятным при использовании клавиатуры, увеличении текста и чтении вспомогательными технологиями.','Используйте семантические кнопки, видимый фокус и явные подписи полей. Не передавайте важное состояние только цветом.','Практика: найдите и забронируйте книгу, используя только Tab, Shift+Tab и Enter. Проверьте, можно ли закрыть диалог клавишей Escape.']};
function read(id){const l=lessons[id];if(!l)return;$('#book-content').innerHTML=`<article class="reader"><div class="eyebrow">Учебная памятка · 3 минуты</div><h2>${l[0]}</h2><p class="note">Краткий материал, созданный для этой демоверсии. Не является полным текстом книги из каталога.</p>${l.slice(1).map((p,i)=>`<h3>${['Основная идея','Пример','Попробуйте сами'][i]}</h3><p>${p}</p>`).join('')}<button class="button outline" data-book="${id}">← К карточке книги</button></article>`}
function action(type,id){const b=books.find(b=>b.id===id);if(!b)return;let message='';if(type==='reserve'){if(b.type==='Electronic'||state.reservations.some(r=>r.id===id)||state.loans.some(l=>l.id===id))return;const ready=available(b)>0;state.reservations.push({id,ready,created:new Date().toISOString()});message=ready?'Книга забронирована. Заявка появилась в кабинете.':'Вы добавлены в лист ожидания.'}if(type==='cancel'){state.reservations=state.reservations.filter(r=>r.id!==id);message='Бронирование отменено.'}if(type==='arrive'){if(route().page!=='staff'||!state.reservations.some(r=>r.id===id&&!r.ready))return;state.stock[id]=(state.stock[id]||0)+1;message='Экземпляр поступил в библиотеку.'}if(type==='issue'){if(route().page!=='staff')return;const r=state.reservations.find(r=>r.id===id);if(!r?.ready||state.loans.some(l=>l.id===id))return;state.reservations=state.reservations.filter(r=>r.id!==id);state.loans.push({id,due:new Date(Date.now()+14*86400000).toISOString(),renewed:false});message='Книга выдана на 14 дней.'}if(type==='return'){if(route().page!=='staff')return;const loan=state.loans.find(l=>l.id===id);if(!loan)return;state.loans=state.loans.filter(l=>l.id!==id);state.history.unshift({...loan,returned:new Date().toISOString()});message='Возврат принят. Экземпляр снова доступен.'}if(type==='renew'){const loan=state.loans.find(l=>l.id===id);if(!loan||loan.renewed)return;if(new Date(loan.due)<new Date()){toast('Срок истёк. Обратитесь к библиотекарю.');return}loan.due=new Date(new Date(loan.due).getTime()+7*86400000).toISOString();loan.renewed=true;message='Срок возврата продлён на 7 дней.'}const promoted=promote();if(promoted)message+=` Бронь «${books.find(b=>b.id===promoted.id).title}» готова к выдаче.`;save();$('#book-dialog').close();render();toast(message)}
function filter(k,v){const {page,params}=route();v?params.set(k,v):params.delete(k);location.hash=page+'?'+params.toString()}
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();const q=new FormData(e.target).get('q').trim();if(['catalog','digital'].includes(route().page))filter('q',q);else location.hash='catalog?q='+encodeURIComponent(q)}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.book)openBook(el.dataset.book);if(el.dataset.read)read(el.dataset.read);if(el.dataset.favorite){const id=el.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();toast(state.favorites.includes(id)?'Добавлено в избранное':'Удалено из избранного')}if(el.dataset.action)action(el.dataset.action,el.dataset.id);if(el.dataset.category!==undefined)filter('category',el.dataset.category);if(el.dataset.tab){tab=el.dataset.tab;render()}if(el.id==='theme'){state.theme=state.theme==='dark'?'light':'dark';save();render()}if(el.classList.contains('dialog-close'))$('#book-dialog').close();if(el.id==='reset-filters')location.hash=route().page;if(el.id==='reset-demo'&&confirm('Удалить избранное, бронирования и историю этой демоверсии?')){const theme=state.theme;state=fresh();state.theme=theme;save();render();toast('Демонстрационные данные сброшены.')}});
document.addEventListener('change',e=>{if(e.target.id==='sort')filter('sort',e.target.value);if(e.target.id==='available')filter('available',e.target.checked?'1':'')});
$('#book-dialog').addEventListener('click',e=>{if(e.target===$('#book-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#book-dialog').addEventListener('close',()=>{if(!$('#book-dialog').open&&route().page.startsWith('book/')){history.replaceState(null,'','#catalog');render()}});
let lastPage=route().page;
window.addEventListener('hashchange',()=>{$('#book-dialog').close();render();window.scrollTo(0,0);const {page}=route(),h=$('#main h1');if(page!==lastPage&&h&&!page.startsWith('book/')){h.tabIndex=-1;h.focus({preventScroll:true})}lastPage=page});render();
